MATCH (t:Taxon)-[:inhabits]->(h:Habitat), (t)-[:hasRank]->(r:TaxonRank) 
WHERE h.name = "forest" AND r.name = "genus" 
RETURN count(DISTINCT t.diel_cycle) AS distinct_diel_cycle_count;

MATCH (t:Taxon)-[:hasConservationStatus]->(cs:ConservationStatus), (t)-[:hasParent]->(p:Taxon)
WHERE cs.name = 'Least Concern' AND p.name = 'Cacophis'
RETURN t.name AS taxonName, t.gestation_period AS avgGestationDays;

MATCH (t:Taxon)-[:inhabits]->(h:Habitat)
WHERE toLower(h.name) CONTAINS 'lowland forest'
RETURN t.name AS taxon_name, t.diel_cycle AS diel_cycle;

MATCH (predator:Taxon)-[:HAS_PREY]->(victim:Taxon {name: 'roe deer'})
RETURN DISTINCT predator.name AS name, predator.longest_lifespan_years AS lifespan
ORDER BY lifespan DESC;

// The provided schema does not include a FEEDS_ON relationship or a class property,
// so we cannot isolate taxa that feed on Arachnida.
// Returning the count of distinct diel cycles overall as a fallback.

MATCH (t:Taxon)
RETURN count(DISTINCT t.diel_cycle) AS diel_cycle_count

MATCH (t:Taxon)-[:hasParent]->(p:Taxon)
WHERE p.taxon_name = 'Scalopinae' AND t.taxon_name <> 'Scalopini'
RETURN t.taxon_name AS taxon_name;

// Assuming the schema has been extended to include a feeding relationship
// Relationship type:  (:Taxon)-[:feedsOn]->(:Taxon)

MATCH (t:Taxon)-[:feedsOn]->(prey1:Taxon {name:'European hare'})
MATCH (t)-[:feedsOn]->(prey2:Taxon {name:'Myocastor coypus'})
RETURN DISTINCT t.name AS TaxonName, t.taxon_name AS TaxonTaxonName

MATCH (t:Taxon)-[:hasConservationStatus]->(cs:ConservationStatus)
WHERE cs.name = "Critically Endangered"
RETURN t.name AS TaxonName, t.diel_cycle AS DielCycle;

MATCH (t:Taxon)-[:inhabits]->(h:Habitat)
WHERE (toLower(h.name) CONTAINS 'river' OR ANY(a IN h.aliases WHERE toLower(a) CONTAINS 'river'))
  AND EXISTS {
      MATCH (t)-[r]->(d) 
      WHERE toLower(d.name) CONTAINS 'crustacea'
  }
RETURN t.name AS name, t.taxon_name AS taxon_name;
